1	import { Buffer } from "node:buffer";
2	
3	import { ProtocolError, ValidationError } from "./errors.js";
4	
5	export const PACKET = Object.freeze({
6	  CONNECT: 1,
7	  CONNACK: 2,
8	  PUBLISH: 3,
9	  PUBACK: 4,
10	  SUBSCRIBE: 8,
11	  SUBACK: 9,
12	  PINGREQ: 12,
13	  PINGRESP: 13,
14	  DISCONNECT: 14,
15	});
16	
17	export const RETURN_CODE = Object.freeze({
18	  ACCEPTED: 0,
19	  UNACCEPTABLE_PROTOCOL_VERSION: 1,
20	  IDENTIFIER_REJECTED: 2,
21	  SERVER_UNAVAILABLE: 3,
22	  BAD_USERNAME_OR_PASSWORD: 4,
23	  NOT_AUTHORIZED: 5,
24	});
25	
26	export const SUBACK_FAILURE = 0x80;
27	export const MAX_REMAINING_LENGTH = 268435455;
28	const MAX_TOPIC_BYTES = 65535;
29	
30	/** Encode a Remaining Length as a 1-4 byte base-128 varint. */
31	export function encodeRemainingLength(value) {
32	  if (!Number.isInteger(value) || value < 0 || value > MAX_REMAINING_LENGTH) {
33	    throw new ValidationError("remaining length must be an integer between 0 and 268435455");
34	  }
35	  const bytes = [];
36	  let remaining = value;
37	  let digit = 0;
38	  do {
39	    digit = remaining % 128;
40	    remaining = Math.floor(remaining / 128);
41	    if (remaining > 0) {
42	      digit |= 0x80;
43	    }
44	    bytes.push(digit);
45	  } while (remaining > 0);
46	  return Buffer.from(bytes);
47	}
48	
49	/** Decode a Remaining Length; returns null when the buffer is incomplete. */
50	export function decodeRemainingLength(buffer, offset = 1) {
51	  let multiplier = 1;
52	  let value = 0;
53	  let index = 0;
54	  for (;;) {
55	    const position = offset + index;
56	    if (position >= buffer.length) {
57	      return null;
58	    }
59	    const digit = buffer[position];
60	    value += (digit & 0x7f) * multiplier;
61	    index += 1;
62	    if ((digit & 0x80) === 0) {
63	      break;
64	    }
65	    if (index >= 4) {
66	      throw new ProtocolError("remaining length must not span more than four bytes");
67	    }
68	    multiplier *= 128;
69	  }
70	  if (value > MAX_REMAINING_LENGTH) {
71	    throw new ProtocolError("remaining length exceeds 268435455");
72	  }
73	  return { value, bytes: index };
74	}
