1	import { ConflictError, NotFoundError, ValidationError } from "./errors.js";
2	import { topicMatches } from "./mqtt.js";
3	import { evaluateCondition, identifier, isIdentifier, matchedValue, parseRule } from "./rules.js";
4	import { computeDelta, parseReportedPatch, parseShadowPatch } from "./shadow.js";
5	import { Store } from "./store.js";
6	import { mergeValues } from "./values.js";
7	
8	const SHADOW_PREFIX = "$shadow/";
9	const TELEMETRY_PREFIX = "$telemetry/";
10	
11	function byId(left, right) {
12	  return left.id < right.id ? -1 : left.id > right.id ? 1 : 0;
13	}
14	
15	function decodePayload(text) {
16	  try {
17	    return JSON.parse(text);
18	  } catch {
19	    return text;
20	  }
21	}
22	
23	export class Service {
24	  constructor(database, options = {}) {
25	    this.store = new Store(database);
26	    this.now = options.now ?? (() => new Date().toISOString());
27	    this.publisher = null;
28	  }
29	
30	  close() {
31	    this.store.close();
32	  }
33	
34	  /** The broker registers itself here so shadow writes can publish deltas. */
35	  setPublisher(publisher) {
36	    this.publisher = publisher;
37	  }
38	
39	  health() {
40	    return { status: "ok" };
41	  }
42	
43	  /**
44	   * Receipt time for a sample in epoch milliseconds. Derived from the
45	   * injectable `now` clock (which returns canonical ISO-8601 UTC) so telemetry
46	   * is stamped by the same clock as shadows and events.
47	   */
48	  clock() {
49	    return Date.parse(this.now());
50	  }
51	
52	  getShadow(rawDeviceId) {
53	    const deviceId = identifier(rawDeviceId, "device id");
54	    const document = this.store.getShadow(deviceId);
55	    if (document === null) {
56	      throw new NotFoundError(`device ${deviceId} has no shadow`);
57	    }
58	    return document;
59	  }
60	
61	  updateShadow(rawDeviceId, raw, key) {
62	    const deviceId = identifier(rawDeviceId, "device id");
63	    const patch = parseShadowPatch(raw);
64	    return this.#idempotent(key, `update-shadow:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
65	  }
66	
67	  reportState(rawDeviceId, raw, key) {
68	    const deviceId = identifier(rawDeviceId, "device id");
69	    const patch = parseReportedPatch(raw);
70	    return this.#idempotent(key, `report-state:${deviceId}`, () => this.applyShadowPatch(deviceId, patch));
71	  }
72	
73	  /**
74	   * Merge a patch into the shadow of `deviceId`, bump the version, evaluate
75	   * shadow rules and publish the delta. Used by HTTP writes and by the
76	   * reserved `$shadow/<deviceId>/update` topic.
77	   */
78	  applyShadowPatch(deviceId, patch) {
79	    const existing = this.store.getShadow(deviceId);
80	    const state = existing === null
81	      ? { desired: {}, reported: {} }
82	      : { desired: structuredClone(existing.state.desired), reported: structuredClone(existing.state.reported) };
83	    if (patch.desired !== null) {
84	      mergeValues(state.desired, patch.desired);
85	    }
86	    if (patch.reported !== null) {
87	      mergeValues(state.reported, patch.reported);
88	    }
89	    const document = {
90	      device_id: deviceId,
91	      state,
92	      delta: computeDelta(state.desired, state.reported),
93	      version: (existing?.version ?? 0) + 1,
94	      updated_at: this.now(),
95	    };
96	    this.store.putShadow(deviceId, document);
97	    this.#evaluateShadowRules(document);
98	    this.#publishDelta(document);
99	    return document;
100	  }
101	
102	  createRule(raw, key) {
103	    const rule = parseRule(raw);
104	    return this.#idempotent(key, `create-rule:${rule.id}`, () => {
105	      if (this.store.getRule(rule.id) !== null) {
106	        throw new ConflictError(`rule ${rule.id} already exists`);
107	      }
108	      this.store.insertRule(rule);
109	      return rule;
110	    });
111	  }
112	
113	  events(query = {}) {
114	    if (query.ruleId !== undefined && query.ruleId !== null) {
115	      identifier(query.ruleId, "rule id");
116	    }
117	    if (query.deviceId !== undefined && query.deviceId !== null) {
118	      identifier(query.deviceId, "device id");
119	    }
120	    return {
121	      events: this.store.listEvents({
122	        ruleId: query.ruleId ?? null,
123	        deviceId: query.deviceId ?? null,
124	        event: query.event ?? null,
125	        source: query.source ?? null,
126	        occurredAfter: query.occurredAfter ?? null,
127	        occurredBefore: query.occurredBefore ?? null,
128	        afterSequence: query.afterSequence ?? null,
129	        limit: query.limit ?? null,
130	      }),
131	    };
132	  }
133	
134	  /**
135	   * Aggregate a device/metric's samples into epoch-aligned buckets over the
136	   * half-open window [from, to). A device that never published a sample is a
137	   * normal result with empty buckets; it never creates a shadow or an event.
138	   */
139	  telemetry(rawDeviceId, query) {
140	    const deviceId = identifier(rawDeviceId, "device id");
141	    const metric = identifier(query.metric, "metric");
142	    const rows = this.store.aggregateTelemetry({
143	      deviceId,
144	      metric,
145	      fromMs: query.from.millis,
146	      toMs: query.to.millis,
147	      bucketSeconds: query.bucketSeconds,
148	      aggregate: query.aggregate,
149	    });
150	    const widthMs = query.bucketSeconds * 1000;
151	    return {
152	      device_id: deviceId,
153	      metric,
154	      from: query.from.canonical,
155	      to: query.to.canonical,
156	      bucket_seconds: query.bucketSeconds,
157	      aggregate: query.aggregate,
158	      buckets: rows.map((row) => ({
159	        start: new Date(row.startMs).toISOString(),
160	        end: new Date(row.startMs + widthMs).toISOString(),
161	        value: row.value,
162	        count: row.count,
163	      })),
164	    };
165	  }
166	
167	  /**
168	   * Called by the broker for every routed publication: the reserved shadow
169	   * topic is applied first, then mqtt-scoped rules are evaluated once for the
170	   * published topic. A `$telemetry/<deviceId>/<metric>` publication carrying a
171	   * single finite JSON number also stores one sample; that capture never
172	   * changes routing, rules or events, and an invalid publication is simply not
173	   * recorded without raising anything.
174	   */
175	  handlePublish(topic, payload) {
176	    this.#recordTelemetry(topic, payload);
177	    if (topic.startsWith(SHADOW_PREFIX)) {
178	      const parts = topic.split("/");
179	      if (parts.length === 3 && parts[2] === "update" && parts[1] !== "") {
180	        let patch = null;
181	        try {
182	          identifier(parts[1], "device id");
183	          patch = parseShadowPatch(JSON.parse(payload.toString("utf8")));
184	        } catch {
185	          // A malformed shadow update is still routed to subscribers but never
186	          // modifies the shadow, and it never raises a broker protocol error.
187	          patch = null;
188	        }
189	        if (patch !== null) {
190	          this.applyShadowPatch(parts[1], patch);
191	        }
192	      }
193	    }
194	    const observation = { topic, payload: decodePayload(payload.toString("utf8")), device_id: null };
195	    for (const rule of this.store.listRules().filter((candidate) => candidate.source === "mqtt")) {
196	      if (topicMatches(rule.topic, topic) && evaluateCondition(rule, observation)) {
197	        this.#emit(rule, { device_id: null, topic, value: matchedValue(rule, observation) });
198	      }
199	    }
200	  }
201	
202	  /**
203	   * Store a telemetry sample for a `$telemetry/<deviceId>/<metric>` publication
204	   * whose payload is a single finite JSON number. Anything else — wrong topic
205	   * shape, illegal device id or metric, a payload that is not a JSON number, or
206	   * NaN/Infinity — stores nothing but is still routed and rule evaluated by the
