295	export class Broker {
296	  constructor(service, options = {}) {
297	    this.service = service;
298	    this.store = service.store;
299	    this.host = options.host ?? "127.0.0.1";
300	    this.port = options.port ?? 1883;
301	    this.maxPacketBytes = options.maxPacketBytes ?? DEFAULT_MAX_PACKET_BYTES;
302	    this.connections = new Set();
303	    // Persistent sessions survive disconnects and restarts: each holds the
304	    // subscriptions granted to the client and the queue of QoS 1 messages
305	    // that are unacknowledged or were never sent.
306	    this.sessions = new Map();
307	    for (const stored of this.store.listSessions()) {
308	      this.sessions.set(stored.clientId, {
309	        clientId: stored.clientId,
310	        subscriptions: new Map(stored.subscriptions.map((subscription) => [subscription.filter, subscription.qos])),
311	        queue: stored.queue,
312	      });
313	    }
314	    this.server = net.createServer((socket) => {
315	      this.connections.add(new ClientConnection(this, socket));
316	    });
317	  }
318	
319	  listen() {
320	    return new Promise((resolve, reject) => {
321	      this.server.once("error", reject);
322	      this.server.listen(this.port, this.host, () => {
323	        this.port = this.server.address().port;
324	        resolve({ host: this.host, port: this.port });
325	      });
326	    });
